-- Local-only contract fixture. Never run against a linked or production database.
do $$ begin
  if current_setting('port')<>'55439' or current_database() not like 'analysis_v2_test%' then raise exception 'Use an isolated local analysis_v2_test database on port 55439'; end if;
  if not exists(select 1 from pg_roles where rolname='anon')then create role anon;end if;
  if not exists(select 1 from pg_roles where rolname='authenticated')then create role authenticated;end if;
  if not exists(select 1 from pg_roles where rolname='service_role')then create role service_role;end if;
end;$$;
create schema auth; create schema app_private;
grant usage on schema auth to public;
create function auth.jwt() returns jsonb language sql stable as $$ select coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb; $$;
create table auth.users(id uuid primary key,raw_app_meta_data jsonb,deleted_at timestamptz);
create table public.organizations(id bigint primary key,name text,slug text,external_reference text,is_active boolean default true);
create table public.organization_members(user_id uuid,organization_id bigint,role text);
create table public.survey_versions(id bigint primary key,name text,reporting_year integer);
create table public.question_definitions(id bigint primary key,stable_key text);
create table public.question_revisions(id bigint primary key,question_id bigint,prompt text,question_type text,options jsonb default '[]',validation jsonb default '{}');
create table public.survey_questions(id bigint primary key,survey_version_id bigint,question_revision_id bigint,display_order integer,visibility_rule jsonb default '{}');
create table public.company_submissions(id bigint primary key,organization_id bigint,survey_version_id bigint,status text);
create table public.submission_snapshots(id bigint generated by default as identity primary key,submission_id bigint,revision_number integer,payload jsonb);
create function app_private.question_is_visible(bigint,jsonb) returns boolean language sql as $$select true;$$;
create function app_private.answer_has_value(value jsonb) returns boolean language sql immutable as $$select value is not null and value not in ('null'::jsonb,'""'::jsonb,'[]'::jsonb,'{}'::jsonb);$$;
create table public.ai_settings(id integer primary key,enabled boolean,monthly_budget_usd numeric,company_monthly_budget_usd numeric,max_output_tokens integer,benchmark_minimum integer);
create table public.ai_usage_events(id uuid primary key default gen_random_uuid(),organization_id bigint,survey_version_id bigint,requested_by uuid,request_type text,provider text,model text,input_tokens integer,output_tokens integer,estimated_cost_usd numeric,actual_cost_usd numeric,status text default 'pending',scope jsonb,created_at timestamptz default now(),completed_at timestamptz,error_code text);
